BEGIN; SET LOCAL search_path=pg_catalog; DO $$ BEGIN IF session_user<>'fixture_bootstrap' OR current_database() !~ '^qual_spin_expiry_[0-9a-f]{32}$' OR inet_server_addr() IS NOT NULL OR current_setting('listen_addresses')<>'' OR current_setting('session_replication_role')<>'origin' THEN RAISE EXCEPTION 'ARCHIVE_SCHEMA_PRIVATE_ALLOCATION_REQUIRED'; END IF; END $$;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='dashboard_user') THEN CREATE ROLE "dashboard_user"; END IF; END $$;
ALTER ROLE "dashboard_user" NOSUPERUSER INHERIT CREATEROLE CREATEDB NOLOGIN REPLICATION NOBYPASSRLS CONNECTION LIMIT -1;
ALTER ROLE "dashboard_user" RESET ALL;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='supabase_admin') THEN CREATE ROLE "supabase_admin"; END IF; END $$;
ALTER ROLE "supabase_admin" SUPERUSER INHERIT CREATEROLE CREATEDB LOGIN REPLICATION BYPASSRLS CONNECTION LIMIT -1;
ALTER ROLE "supabase_admin" RESET ALL;
ALTER ROLE "supabase_admin" SET "search_path" TO "$user","public","auth","extensions";
ALTER ROLE "supabase_admin" SET "log_statement" TO 'none';
ALTER ROLE "supabase_admin" SET "statement_timeout" TO '0';
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('rolname',rolname,'rolsuper',rolsuper,'rolinherit',rolinherit,'rolcreaterole',rolcreaterole,'rolcreatedb',rolcreatedb,'rolcanlogin',rolcanlogin,'rolreplication',rolreplication,'rolbypassrls',rolbypassrls,'rolconnlimit',rolconnlimit,'rolconfig',rolconfig) INTO actual FROM pg_roles WHERE rolname='dashboard_user'; IF actual IS DISTINCT FROM '{"rolname": "dashboard_user", "rolsuper": false, "rolinherit": true, "rolcreaterole": true, "rolcreatedb": true, "rolcanlogin": false, "rolreplication": true, "rolbypassrls": false, "rolconnlimit": -1, "rolconfig": null}'::jsonb OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=(SELECT oid FROM pg_roles WHERE rolname='dashboard_user')) THEN RAISE EXCEPTION 'ARCHIVE_EXTRA_ROLE_CHANGED: dashboard_user' USING DETAIL=actual::text; END IF; END $$;
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('rolname',rolname,'rolsuper',rolsuper,'rolinherit',rolinherit,'rolcreaterole',rolcreaterole,'rolcreatedb',rolcreatedb,'rolcanlogin',rolcanlogin,'rolreplication',rolreplication,'rolbypassrls',rolbypassrls,'rolconnlimit',rolconnlimit,'rolconfig',rolconfig) INTO actual FROM pg_roles WHERE rolname='supabase_admin'; IF actual IS DISTINCT FROM '{"rolname": "supabase_admin", "rolsuper": true, "rolinherit": true, "rolcreaterole": true, "rolcreatedb": true, "rolcanlogin": true, "rolreplication": true, "rolbypassrls": true, "rolconnlimit": -1, "rolconfig": ["search_path=\"$user\", public, auth, extensions", "log_statement=none", "statement_timeout=0"]}'::jsonb OR EXISTS(SELECT 1 FROM pg_auth_members WHERE member=(SELECT oid FROM pg_roles WHERE rolname='supabase_admin')) THEN RAISE EXCEPTION 'ARCHIVE_EXTRA_ROLE_CHANGED: supabase_admin' USING DETAIL=actual::text; END IF; END $$;
ALTER SCHEMA "auth" OWNER TO "supabase_admin";
DO $$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END who FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='auth' LOOP EXECUTE 'REVOKE ALL ON SCHEMA "auth" FROM '||r.who; END LOOP; END $$;
SET LOCAL ROLE "supabase_admin";
GRANT USAGE ON SCHEMA "auth" TO "supabase_admin";
GRANT CREATE ON SCHEMA "auth" TO "supabase_admin";
GRANT USAGE ON SCHEMA "auth" TO "anon";
GRANT USAGE ON SCHEMA "auth" TO "authenticated";
GRANT USAGE ON SCHEMA "auth" TO "service_role";
GRANT USAGE ON SCHEMA "auth" TO "supabase_auth_admin";
GRANT CREATE ON SCHEMA "auth" TO "supabase_auth_admin";
GRANT USAGE ON SCHEMA "auth" TO "dashboard_user";
GRANT CREATE ON SCHEMA "auth" TO "dashboard_user";
GRANT USAGE ON SCHEMA "auth" TO "postgres";
RESET ROLE;
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',(SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(coalesce(nspacl,acldefault('n',nspowner))) v)) INTO actual FROM pg_namespace WHERE nspname='auth'; IF actual IS DISTINCT FROM '{"owner": "supabase_admin", "acl": ["anon=U/supabase_admin", "authenticated=U/supabase_admin", "dashboard_user=UC/supabase_admin", "postgres=U/supabase_admin", "service_role=U/supabase_admin", "supabase_admin=UC/supabase_admin", "supabase_auth_admin=UC/supabase_admin"]}'::jsonb THEN RAISE EXCEPTION 'ARCHIVE_SCHEMA_AUTHORITY_CHANGED: auth' USING DETAIL=actual::text; END IF; END $$;
ALTER SCHEMA "extensions" OWNER TO "postgres";
DO $$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END who FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='extensions' LOOP EXECUTE 'REVOKE ALL ON SCHEMA "extensions" FROM '||r.who; END LOOP; END $$;
SET LOCAL ROLE "postgres";
GRANT USAGE ON SCHEMA "extensions" TO "postgres";
GRANT CREATE ON SCHEMA "extensions" TO "postgres";
GRANT USAGE ON SCHEMA "extensions" TO "anon";
GRANT USAGE ON SCHEMA "extensions" TO "authenticated";
GRANT USAGE ON SCHEMA "extensions" TO "service_role";
GRANT USAGE ON SCHEMA "extensions" TO "dashboard_user";
GRANT CREATE ON SCHEMA "extensions" TO "dashboard_user";
RESET ROLE;
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',(SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(coalesce(nspacl,acldefault('n',nspowner))) v)) INTO actual FROM pg_namespace WHERE nspname='extensions'; IF actual IS DISTINCT FROM '{"owner": "postgres", "acl": ["anon=U/postgres", "authenticated=U/postgres", "dashboard_user=UC/postgres", "postgres=UC/postgres", "service_role=U/postgres"]}'::jsonb THEN RAISE EXCEPTION 'ARCHIVE_SCHEMA_AUTHORITY_CHANGED: extensions' USING DETAIL=actual::text; END IF; END $$;
ALTER SCHEMA "public" OWNER TO "pg_database_owner";
DO $$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END who FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='public' LOOP EXECUTE 'REVOKE ALL ON SCHEMA "public" FROM '||r.who; END LOOP; END $$;
SET LOCAL ROLE "postgres";
GRANT USAGE ON SCHEMA "public" TO "pg_database_owner";
GRANT CREATE ON SCHEMA "public" TO "pg_database_owner";
GRANT USAGE ON SCHEMA "public" TO PUBLIC;
GRANT USAGE ON SCHEMA "public" TO "postgres";
GRANT USAGE ON SCHEMA "public" TO "anon";
GRANT USAGE ON SCHEMA "public" TO "authenticated";
GRANT USAGE ON SCHEMA "public" TO "service_role";
RESET ROLE;
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',(SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(coalesce(nspacl,acldefault('n',nspowner))) v)) INTO actual FROM pg_namespace WHERE nspname='public'; IF actual IS DISTINCT FROM '{"owner": "pg_database_owner", "acl": ["=U/pg_database_owner", "anon=U/pg_database_owner", "authenticated=U/pg_database_owner", "pg_database_owner=UC/pg_database_owner", "postgres=U/pg_database_owner", "service_role=U/pg_database_owner"]}'::jsonb THEN RAISE EXCEPTION 'ARCHIVE_SCHEMA_AUTHORITY_CHANGED: public' USING DETAIL=actual::text; END IF; END $$;
ALTER SCHEMA "smarter_private" OWNER TO "postgres";
DO $$ DECLARE r record; BEGIN FOR r IN SELECT DISTINCT CASE WHEN a.grantee=0 THEN 'PUBLIC' ELSE quote_ident(pg_get_userbyid(a.grantee)) END who FROM pg_namespace n CROSS JOIN LATERAL aclexplode(coalesce(n.nspacl,acldefault('n',n.nspowner))) a WHERE n.nspname='smarter_private' LOOP EXECUTE 'REVOKE ALL ON SCHEMA "smarter_private" FROM '||r.who; END LOOP; END $$;
SET LOCAL ROLE "postgres";
GRANT USAGE ON SCHEMA "smarter_private" TO "postgres";
GRANT CREATE ON SCHEMA "smarter_private" TO "postgres";
GRANT USAGE ON SCHEMA "smarter_private" TO "anon";
GRANT USAGE ON SCHEMA "smarter_private" TO "authenticated";
GRANT USAGE ON SCHEMA "smarter_private" TO "service_role";
RESET ROLE;
DO $$ DECLARE actual jsonb; BEGIN SELECT jsonb_build_object('owner',pg_get_userbyid(nspowner),'acl',(SELECT jsonb_agg(v::text ORDER BY v::text) FROM unnest(coalesce(nspacl,acldefault('n',nspowner))) v)) INTO actual FROM pg_namespace WHERE nspname='smarter_private'; IF actual IS DISTINCT FROM '{"owner": "postgres", "acl": ["anon=U/postgres", "authenticated=U/postgres", "postgres=UC/postgres", "service_role=U/postgres"]}'::jsonb THEN RAISE EXCEPTION 'ARCHIVE_SCHEMA_AUTHORITY_CHANGED: smarter_private' USING DETAIL=actual::text; END IF; END $$;
COMMIT;
